 $('qr-png').onclick=async()=>{try{if(current)download(await toBlob($('qr-canvas')),'quicktiny-qr.png');}catch(e){fail(e);}};$('qr-svg').onclick=()=>{if(current){const {fg,bg}=colors();download(new Blob([qrSVG(current,fg,bg)],{type:'image/svg+xml'}),'quicktiny-qr.svg');}};
