EXTRA_TOOLS['color-palette-extractor']=function(){
 $('tool').innerHTML=panel(`${picker()}<div class="two-cols">${field('palette-count','Palette size','number',5,'min="2" max="12"')}${check('palette-white','Ignore near-white pixels')}</div>${button('palette-run','Extract palette',true,'spark')}<div id="palette-swatches" style="display:flex;gap:10px;flex-wrap:wrap;margin:22px 0"></div><div class="two-cols">${field('palette-text','Text color','color','#302720')}${field('palette-bg','Contrast background','color','#faf7f2')}</div><div id="contrast-preview" style="padding:22px;border:1px solid var(--line);border-radius:8px;font-size:22px">A little clarity. Un peu de clarté.</div><div class="result-grid"><div class="result-row"><span>Contrast ratio</span><strong id="contrast-ratio" data-no-i18n></strong></div>${[['contrast-aa','Normal text AA'],['contrast-large','Large text AA'],['contrast-aaa','Normal text AAA']].map(([id,label])=>`<div class="result-row"><span>${label}</span><strong id="${id}"></strong></div>`).join('')}</div>${actions([button('palette-css','Export CSS',false,'download'),button('palette-tailwind','Export Tailwind JSON',false,'download')])}<p class="subtle"><a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener">W3C WCAG contrast</a></p>`);
 let palette=[];function updateContrast(){const fg=$('palette-text').value,bg=$('palette-bg').value,n=contrast(fg,bg);$('contrast-preview').style.color=fg;$('contrast-preview').style.background=bg;$('contrast-ratio').textContent=n.toFixed(2)+':1';$('contrast-aa').textContent=n>=4.5?'Pass':'Fail';$('contrast-large').textContent=n>=3?'Pass':'Fail';$('contrast-aaa').textContent=n>=7?'Pass':'Fail';}
 function buttons(){['palette-css','palette-tailwind'].forEach(id=>$(id).disabled=!palette.length);}buttons();updateContrast();$('palette-text').oninput=updateContrast;$('palette-bg').oninput=updateContrast;
 $('palette-run').onclick=async()=>{let loaded;try{loaded=await loadImage($('design-file').files[0]);const canvas=sizedCanvas(240,Math.max(1,Math.round(240*loaded.height/loaded.width)));const scale=Math.min(1,240/loaded.width,240/loaded.height);canvas.width=Math.max(1,Math.round(loaded.width*scale));canvas.height=Math.max(1,Math.round(loaded.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(loaded.image,0,0,canvas.width,canvas.height);const count=Number($('palette-count').value);if(!Number.isInteger(count)||count<2||count>12)throw Error('Choose between 2 and 12 palette colors.');palette=extractPalette(ctx.getImageData(0,0,canvas.width,canvas.height).data,count,$('palette-white').checked);if(!palette.length)throw Error('No opaque colors found. Try disabling the white filter.');$('palette-swatches').replaceChildren();palette.forEach((p,i)=>{const b=document.createElement('button');b.className='btn';b.style.cssText=`display:flex;flex-direction:column;gap:8px;padding:10px;min-width:85px;flex:1`;b.type='button';b.setAttribute('aria-label',p.color);const sample=document.createElement('span');sample.style.cssText=`display:block;width:100%;height:66px;border-radius:5px;background:${p.color}`;const label=document.createElement('strong');label.dataset.noI18n='';label.textContent=p.color.toUpperCase();const share=document.createElement('span');share.dataset.noI18n='';share.textContent=Math.round(p.weight*100)+'%';b.append(sample,label,share);b.onclick=()=>{copy(p.color);$('palette-text').value=p.color;updateContrast();};$('palette-swatches').append(b);});$('palette-text').value=palette[0].color;updateContrast();buttons();message('Palette ready. Click a color to copy its hex value.');}catch(e){palette=[];buttons();fail(e);}finally{loaded?.close();}};
 $('palette-css').onclick=()=>download(new Blob([':root {\n'+palette.map((p,i)=>`  --brand-${i+1}: ${p.color};`).join('\n')+'\n}\n'],{type:'text/css'}),'brand-palette.css');$('palette-tailwind').onclick=()=>download(new Blob([JSON.stringify({theme:{extend:{colors:{brand:Object.fromEntries(palette.map((p,i)=>[String((i+1)*100),p.color]))}}}},null,2)+'\n'],{type:'application/json'}),'tailwind-palette.json');
 const clearPalette=()=>{palette=[];$('palette-swatches').replaceChildren();buttons();message('');};$('design-file').onchange=clearPalette;$('palette-count').oninput=clearPalette;$('palette-white').onchange=clearPalette;
};
EXTRA_TOOLS['product-photo-studio']=function(){
 $('tool').innerHTML=panel(`${picker()}<div class="two-cols">${field('photo-tolerance','Background tolerance','range',35,'min="0" max="150"')}${field('photo-brush','Brush size (px)','range',30,'min="3" max="180"')}${select('photo-mode','Editing tool',[['pick','Pick and remove background'],['erase','Erase brush'],['restore','Restore brush']])}${select('photo-size','Output size',[['1024','1024 × 1024'],['1600','1600 × 1600'],['2000','2000 × 2000']])}${field('photo-margin','Margin (%)','number',10,'min="0" max="40"')}${select('photo-transparent','Canvas background',[['solid','Solid background'],['transparent','Transparent PNG']])}${field('photo-bg','Background color','color','#ffffff')}</div>${actions([button('photo-remove','Remove edge background',true,'spark'),button('photo-undo','Undo last edit'),button('photo-reset','Reset image')])}<p id="photo-instruction" class="subtle">Click the background on the preview to remove its connected color region.</p>${canvasMarkup('photo-canvas')}${actions([button('photo-export','Export product photo',true,'download')])}`);
 const canvas=$('photo-canvas');canvas.width=canvas.height=1;let original=null,undo=null,drawing=false,last=null,generation=0;
 function enabled(on){['photo-remove','photo-undo','photo-reset','photo-export'].forEach(id=>$(id).disabled=!on);$('photo-undo').disabled=!undo;}
 enabled(false);function snapshot(){undo=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height);$('photo-undo').disabled=false;}
 function remove(seed){const ctx=canvas.getContext('2d'),pixels=ctx.getImageData(0,0,canvas.width,canvas.height);snapshot();const data=floodRemove(pixels.data,canvas.width,canvas.height,seed,Number($('photo-tolerance').value));pixels.data.set(data);ctx.putImageData(pixels,0,0);message('Background removed. Refine with the brush if needed.');}
 $('design-file').onchange=async()=>{const version=++generation;let loaded;try{loaded=await loadImage($('design-file').files[0]);if(version!==generation)return;const scale=Math.min(1,1600/loaded.width,1600/loaded.height);canvas.width=Math.max(1,Math.round(loaded.width*scale));canvas.height=Math.max(1,Math.round(loaded.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(loaded.image,0,0,canvas.width,canvas.height);original=sizedCanvas(canvas.width,canvas.height);original.getContext('2d').drawImage(canvas,0,0);undo=null;enabled(true);message('Image ready.');}catch(e){original=null;undo=null;enabled(false);fail(e);}finally{loaded?.close();}};
 $('photo-remove').onclick=()=>{if(original)try{remove(0);}catch(e){fail(e);}};$('photo-reset').onclick=()=>{if(original){snapshot();canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);canvas.getContext('2d').drawImage(original,0,0);message('Image ready.');}};$('photo-undo').onclick=()=>{if(undo){const ctx=canvas.getContext('2d'),current=ctx.getImageData(0,0,canvas.width,canvas.height);ctx.putImageData(undo,0,0);undo=current;message('');}};
 const point=e=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(canvas.width-1,(e.clientX-r.left)/r.width*canvas.width)),y:Math.max(0,Math.min(canvas.height-1,(e.clientY-r.top)/r.height*canvas.height))};};
 function brush(p){const ctx=canvas.getContext('2d'),radius=Number($('photo-brush').value)/2;ctx.save();if($('photo-mode').value==='erase'){ctx.globalCompositeOperation='destination-out';ctx.strokeStyle='#000';ctx.lineWidth=radius*2;ctx.lineCap='round';ctx.beginPath();ctx.moveTo((last||p).x,(last||p).y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.fill();}else{const from=last||p,steps=Math.max(1,Math.ceil(Math.hypot(p.x-from.x,p.y-from.y)/(radius*.5)));for(let i=0;i<=steps;i++){ctx.save();ctx.beginPath();ctx.arc(from.x+(p.x-from.x)*i/steps,from.y+(p.y-from.y)*i/steps,radius,0,Math.PI*2);ctx.clip();ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(original,0,0);ctx.restore();}}ctx.restore();last=p;}
 canvas.onpointerdown=e=>{if(!original)return;e.preventDefault();const p=point(e);if($('photo-mode').value==='pick'){try{remove(Math.floor(p.y)*canvas.width+Math.floor(p.x));}catch(error){fail(error);}return;}snapshot();drawing=true;last=p;canvas.setPointerCapture?.(e.pointerId);brush(p);};canvas.onpointermove=e=>{if(drawing)brush(point(e));};const finish=()=>{drawing=false;last=null;};canvas.onpointerup=finish;canvas.onpointercancel=finish;
 $('photo-mode').onchange=()=>{$('photo-instruction').textContent=$('photo-mode').value==='pick'?'Click the background on the preview to remove its connected color region.':'Use the brush on the preview. Changes affect only your local copy.';};
 $('photo-export').onclick=async()=>{try{if(!original)throw Error('Choose an image first.');const size=validSize($('photo-size').value),margin=Number($('photo-margin').value);if(!Number.isFinite(margin)||margin<0||margin>40)throw Error('Enter valid image dimensions between 1 and 8,192 pixels.');const bounds=alphaBounds(canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height);if(!bounds)throw Error('No foreground remains. Undo or reset, then reduce tolerance.');const output=sizedCanvas(size,size),ctx=output.getContext('2d');if($('photo-transparent').value==='solid'){ctx.fillStyle=$('photo-bg').value;ctx.fillRect(0,0,size,size);}const r=containRect(bounds.width,bounds.height,size,size,size*margin/100);ctx.drawImage(canvas,bounds.x,bounds.y,bounds.width,bounds.height,r.x,r.y,r.width,r.height);download(await toBlob(output),'product-photo.png');message('Download is ready.');}catch(e){fail(e);}};
};
