 $('tool').innerHTML=panel(`${picker()}<div class="options">${socialPresets.map(([id,label,w,h],i)=>check('social-'+id,label+' · '+w+' × '+h,i<3)).join('')}</div><div class="two-cols">${select('social-fit','Fit mode',[['cover','Cover / crop'],['contain','Contain / letterbox']])}${field('social-bg','Background color','color','#f5e8dc')}${field('social-x','Focal point X','range',50,'min="0" max="100"')}${field('social-y','Focal point Y','range',50,'min="0" max="100"')}${select('social-preview','Preview',socialPresets.map(([id,label])=>[id,label]))}</div>${canvasMarkup('social-canvas')}${actions([button('social-export','Export selected sizes',true,'download'),button('social-zip','Download ZIP',false,'download')])}<div id="social-results"></div>`);
 let image=null,loaded=null,results=[],urls=[],version=0;const clear=()=>{urls.forEach(u=>URL.revokeObjectURL(u));urls=[];results=[];$('social-results').replaceChildren();$('social-zip').disabled=true;};$('social-canvas').width=$('social-canvas').height=1;$('social-zip').disabled=true;$('social-export').disabled=true;
 const options=()=>({mode:$('social-fit').value,background:$('social-bg').value,fx:Number($('social-x').value)/100,fy:Number($('social-y').value)/100});
 function preview(){if(!image)return;const preset=socialPresets.find(x=>x[0]===$('social-preview').value),canvas=$('social-canvas');canvas.width=Math.round(preset[2]*Math.min(1,720/preset[2],720/preset[3]));canvas.height=Math.round(preset[3]*canvas.width/preset[2]);paintImage(canvas.getContext('2d'),image,canvas.width,canvas.height,options());}
