 $('tool').innerHTML=panel(`${picker()}${field('kb-limit','Max file size (KB)','number',100,'min="1" max="100000" step="any"')}<div class="options">${[20,50,100,200,500].map(n=>`<button class="small-button" type="button" data-kb="${n}">${n} KB</button>`).join('')}</div>${button('kb-run','Compress to limit',true,'spark')}<div id="kb-results"></div>`);
 let urls=[],version=0;const clear=()=>{version++;urls.forEach(u=>URL.revokeObjectURL(u));urls=[];$('kb-results').replaceChildren();message('');};$('design-file').onchange=clear;$('kb-limit').oninput=clear;document.querySelectorAll('[data-kb]').forEach(b=>b.onclick=()=>{$('kb-limit').value=b.dataset.kb;clear();});
 $('kb-run').onclick=async()=>{let loaded;try{clear();const run=version,limit=Number($('kb-limit').value)*1000;if(!Number.isFinite(limit)||limit<1000||limit>100000000)throw Error('Maximum size must be between 1 and 100,000 KB.');loaded=await loadImage($('design-file').files[0]);if(run!==version)return;$('kb-run').disabled=true;const result=await fitJPEG(loaded.image,Math.floor(limit));if(run!==version)return;if(result.blob.size>limit)throw Error('The size limit is too small for a valid JPG. Increase it.');const p=document.createElement('p');p.dataset.noI18n='';p.className='subtle';p.textContent=`${loaded.width} × ${loaded.height} → ${result.width} × ${result.height} px · ${formatBytes(result.blob.size)} ≤ ${Math.floor(limit).toLocaleString()} bytes`;$('kb-results').append(p);urls.push(resultLink($('kb-results'),result.blob,filenameStem($('design-file').files[0].name)+'-under-'+$('kb-limit').value+'kb.jpg','Download JPG'));message('Download is ready.');}catch(e){fail(e);}finally{loaded?.close();$('kb-run').disabled=false;}};
