EXTRA_TOOLS['image-converter']=function(){
 $('tool').innerHTML=panel(`${picker(true)}<div class="two-cols">${select('convert-format','Output format',[['image/jpeg','JPG (white background)'],['image/png','PNG (transparency)'],['image/webp','WebP'],['image/avif','AVIF (if supported)']])}${field('convert-quality','Quality','range',90,'min="10" max="100"')}${field('convert-width','Maximum width (px, 0 = original)','number',0,'min="0" max="16384"')}</div>${actions([button('convert-run','Convert images',true,'spark'),button('convert-zip','Download ZIP',false,'download')])}<div id="convert-results"></div>`);
 let results=[],urls=[],version=0;function clear(){version++;urls.forEach(u=>URL.revokeObjectURL(u));urls=[];results=[];$('convert-results').replaceChildren();$('convert-zip').disabled=true;message('');}clear();$('design-file').onchange=clear;document.querySelectorAll('#tool input:not([type=file]),#tool select').forEach(el=>el.oninput=()=>{clear();$('convert-quality').disabled=$('convert-format').value==='image/png';});
 $('convert-run').onclick=async()=>{try{clear();const run=version,files=[...$('design-file').files],width=Number($('convert-width').value),type=$('convert-format').value,quality=Number($('convert-quality').value)/100;if(!files.length)throw Error('Choose one or more images first.');if(!Number.isInteger(width)||width<0||width>16384)throw Error('Maximum width must be between 0 and 16,384 pixels.');$('convert-run').disabled=true;let failed=0;for(let i=0;i<files.length;i++){if(run!==version)break;let loaded;try{loaded=await loadImage(files[i],true);const scale=Math.min(1,width?width/loaded.width:1,16384/loaded.width,16384/loaded.height,Math.sqrt(32000000/(loaded.width*loaded.height)));const canvas=sizedCanvas(Math.max(1,Math.round(loaded.width*scale)),Math.max(1,Math.round(loaded.height*scale)));const ctx=canvas.getContext('2d');if(type==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(loaded.image,0,0,canvas.width,canvas.height);const blob=await toBlob(canvas,type,quality);if(run!==version)break;const ext=type==='image/jpeg'?'jpg':type.split('/')[1],name=String(i+1).padStart(3,'0')+'-'+filenameStem(files[i].name)+'.'+ext;results.push({name,blob});urls.push(resultLink($('convert-results'),blob,name));canvas.width=canvas.height=1;}catch(e){if(run!==version)break;failed++;const p=document.createElement('p');p.className='message error';const filename=document.createElement('span');filename.dataset.noI18n='';filename.textContent=files[i].name+': ';const error=document.createElement('span');error.textContent=FR_STRINGS[e.message]?e.message:'Image processing failed. Try another image or setting.';p.append(filename,error);$('convert-results').append(p);}finally{loaded?.close();}await new Promise(resolve=>setTimeout(resolve,0));}if(run===version){$('convert-zip').disabled=!results.length;say(`${results.length} converted · ${failed} failed`,`${results.length} convertie(s) · ${failed} en échec`,failed>0);}}catch(e){fail(e);}finally{$('convert-run').disabled=false;}};
 $('convert-zip').onclick=async()=>{try{const current=[...results];if(!current.length)return;$('convert-zip').disabled=true;const files=[];for(const r of current)files.push({name:r.name,bytes:new Uint8Array(await r.blob.arrayBuffer())});download(Core.zip(files),'converted-images.zip');message('Batch ZIP is ready.');}catch(e){fail(e);}finally{$('convert-zip').disabled=!results.length;}};
};
function wrapText(ctx,text,maxWidth){const paragraphs=String(text).replace(/\r/g,'').split('\n'),lines=[];for(const paragraph of paragraphs){let line='';for(const word of paragraph.split(/\s+/).filter(Boolean)){if(!line){if(ctx.measureText(word).width>maxWidth){let part='';for(const char of word){if(part&&ctx.measureText(part+char).width>maxWidth){lines.push(part);part=char;}else part+=char;}line=part;}else line=word;}else if(ctx.measureText(line+' '+word).width<=maxWidth)line+=' '+word;else{lines.push(line);line=word;}}lines.push(line);}return lines;}
EXTRA_CORE.design.wrapText=wrapText;
EXTRA_TOOLS['youtube-thumbnail-maker']=function(){
 $('tool').innerHTML=panel(`${picker()}${area('thumb-title','Title','YOUR NEXT\nBIG IDEA',2)}${field('thumb-subtitle','Supporting text','text','Make it happen')}<div class="two-cols">${select('thumb-placement','Text placement',[['left','Left'],['right','Right'],['center','Center']])}${field('thumb-font','Font size (px)','number',112,'min="30" max="180"')}${field('thumb-text','Title color','color','#ffffff')}${field('thumb-outline','Outline color','color','#302720')}${field('thumb-accent','Accent color','color','#e09d63')}${field('thumb-dim','Darken photo (%)','range',50,'min="0" max="90"')}${field('thumb-x','Focal point X','range',50,'min="0" max="100"')}${field('thumb-y','Focal point Y','range',50,'min="0" max="100"')}</div>${button('thumb-preview','Preview thumbnail',true,'spark')}${canvasMarkup('thumb-canvas')}<p class="subtle">1280 × 720 · JPG under 2 MB</p>${button('thumb-download','Download JPG',true,'download')}`);
 $('thumb-title').maxLength=300;$('thumb-subtitle').maxLength=200;const canvas=$('thumb-canvas');canvas.width=1280;canvas.height=720;let loaded=null,version=0;
 function render(){const title=$('thumb-title').value.trim();if(!title)throw Error('Enter a title for your thumbnail.');const ctx=canvas.getContext('2d');ctx.clearRect(0,0,1280,720);ctx.fillStyle='#302720';ctx.fillRect(0,0,1280,720);if(loaded)paintImage(ctx,loaded.image,1280,720,{fx:Number($('thumb-x').value)/100,fy:Number($('thumb-y').value)/100});const dim=Number($('thumb-dim').value)/100;const overlay=ctx.createLinearGradient(0,0,1280,0);const pos=$('thumb-placement').value;if(pos==='left'){overlay.addColorStop(0,`rgba(0,0,0,${Math.min(.95,dim+.25)})`);overlay.addColorStop(1,`rgba(0,0,0,${dim*.3})`);}else if(pos==='right'){overlay.addColorStop(1,`rgba(0,0,0,${Math.min(.95,dim+.25)})`);overlay.addColorStop(0,`rgba(0,0,0,${dim*.3})`);}else{overlay.addColorStop(0,`rgba(0,0,0,${dim})`);overlay.addColorStop(1,`rgba(0,0,0,${dim})`);}ctx.fillStyle=overlay;ctx.fillRect(0,0,1280,720);let font=validSize($('thumb-font').value,30,180),lines=[];const maxWidth=pos==='center'?1120:960;for(let i=0;i<50;i++){ctx.font=`900 ${font}px Arial, sans-serif`;lines=wrapText(ctx,title,maxWidth);if(lines.length*font*1.08<=520||font<=25)break;font-=2;}const startY=720/2-lines.length*font*1.08/2+(font*.82),x=pos==='left'?70:pos==='right'?1210:640;ctx.textAlign=pos==='center'?'center':pos==='right'?'right':'left';ctx.textBaseline='alphabetic';ctx.lineJoin='round';ctx.lineWidth=Math.max(4,font*.075);ctx.strokeStyle=$('thumb-outline').value;ctx.fillStyle=$('thumb-text').value;lines.forEach((line,i)=>{ctx.strokeText(line,x,startY+i*font*1.08);ctx.fillText(line,x,startY+i*font*1.08);});const sub=$('thumb-subtitle').value.trim();if(sub){ctx.font='600 31px Arial, sans-serif';ctx.fillStyle=$('thumb-accent').value;const subLines=wrapText(ctx,sub,1120).slice(0,2);subLines.forEach((line,i)=>ctx.fillText(line,x,Math.min(645,startY+lines.length*font*1.08+28)+i*35));}ctx.fillStyle=$('thumb-accent').value;ctx.fillRect(pos==='right'?1080:70,42,130,9);}
 $('thumb-preview').onclick=()=>{try{render();message('Image ready.');}catch(e){fail(e);}};$('design-file').onchange=async()=>{const run=++version;let candidate;try{candidate=await loadImage($('design-file').files[0]);if(run!==version){candidate.close();return;}loaded?.close();loaded=candidate;render();message('Image ready.');}catch(e){candidate?.close();fail(e);}};document.querySelectorAll('#tool input:not([type=file]),#tool textarea,#tool select').forEach(el=>el.addEventListener('input',()=>{try{render();message('');}catch(e){fail(e);}}));
 $('thumb-download').onclick=async()=>{try{render();const result=await fitJPEG(canvas,2000000);download(result.blob,'youtube-thumbnail.jpg');message('Download is ready.');}catch(e){fail(e);}};render();
};
const resumeFields=[['name','Full name'],['headline','Professional headline'],['email','Email'],['phone','Phone'],['location','Location'],['website','Website'],['summary','Profile / summary'],['experience','Experience'],['education','Education'],['skills','Skills'],['projects','Projects / additional information']];
function resumeText(data){return [data.name,data.headline,[data.email,data.phone,data.location,data.website].filter(Boolean).join(' · '),...resumeFields.slice(6).flatMap(([id,label])=>data[id]?[label.toUpperCase(),data[id]]:[])].filter(Boolean).join('\n\n')+'\n';}
function validateResume(value){if(!value||value.format!=='quicktiny-cv'||value.version!==1||!value.data||typeof value.data!=='object')throw Error('This is not a valid QuickTiny resume JSON file.');const data={};for(const [id] of resumeFields){const content=value.data[id];if(content!==undefined&&(typeof content!=='string'||content.length>50000))throw Error('This is not a valid QuickTiny resume JSON file.');data[id]=content||'';}const accent=value.data.accent||'#a54d2e';colorRGB(accent);data.accent=accent;return data;}
function resumeHTML(data,{language='en',print=false}={}){const label=s=>language==='fr'?(FR_STRINGS[s]||s):s,accent=/^#[0-9a-f]{6}$/i.test(data.accent)?data.accent:'#a54d2e';const heading=(content,fallback)=>`<h1 ${content?'data-no-i18n':''} style="font-size:30px;line-height:1.2;margin:0 0 8px;overflow-wrap:anywhere">${escape(content||label(fallback))}</h1>`;let html=`<article style="font:14px/1.55 Arial,sans-serif;color:#302720;background:white;max-width:800px;margin:auto;padding:35px;border-top:7px solid ${accent};overflow-wrap:anywhere">${heading(data.name,'Your name')}<p ${data.headline?'data-no-i18n':''} style="font-size:17px;margin:0 0 17px;color:${accent}">${escape(data.headline||label('Your professional headline'))}</p><p data-no-i18n style="font-size:12px;margin:0 0 24px">${escape([data.email,data.phone,data.location,data.website].filter(Boolean).join(' · '))}</p>`;for(const [id,title] of resumeFields.slice(6)){if(!data[id]&&id!=='summary')continue;html+=`<section style="margin-top:22px;break-inside:auto"><h2 style="font-size:14px;text-transform:uppercase;letter-spacing:1px;border-bottom:1px solid #dfd5cb;padding-bottom:5px;color:${accent};margin:0 0 9px">${escape(label(title))}</h2><div ${data[id]?'data-no-i18n':''} style="white-space:pre-wrap">${escape(data[id]||label('Add your professional summary.'))}</div></section>`;}return html+'</article>';}
EXTRA_CORE.design.resumeText=resumeText;EXTRA_CORE.design.resumeHTML=resumeHTML;EXTRA_CORE.design.validateResume=validateResume;
EXTRA_TOOLS['cv-builder']=function(){
 $('tool').innerHTML=panel(`<h3>Resume details</h3><div class="two-cols">${resumeFields.slice(0,6).map(([id,label])=>field('cv-'+id,label,id==='email'?'email':id==='phone'?'tel':'text')).join('')}</div>${resumeFields.slice(6).map(([id,label])=>area('cv-'+id,label,'',id==='experience'?7:4)).join('')}${field('cv-accent','Resume accent','color','#a54d2e')}${actions([button('cv-print','Print / Save as PDF',true,'download'),button('cv-json','Export resume JSON'),button('cv-txt','Download plain text'),button('cv-sample','Sample resume')])}${field('cv-import','Import resume JSON','file','','accept="application/json,.json"')}<div class="output-section"><h3>Resume preview</h3><div id="cv-preview" style="background:#eee6dc;padding:12px;border-radius:10px;max-height:1000px;overflow:auto"></div></div>`);
 function data(){return Object.fromEntries([...resumeFields.map(([id])=>[id,$('cv-'+id).value]),['accent',$('cv-accent').value]]);}
 function render(){$('cv-preview').innerHTML=resumeHTML(data());}
 document.querySelectorAll('#tool input:not([type=file]),#tool textarea').forEach(el=>el.oninput=render);
 $('cv-sample').onclick=()=>{const french=document.documentElement.lang==='fr';const value=french?{name:'Camille Martin',headline:'Cheffe de projet numérique',email:'camille@example.com',location:'Lyon, France',summary:'Cheffe de projet avec cinq ans d’expérience dans la conception de services numériques. Coordination d’équipes et livraison de projets accessibles.',experience:'Cheffe de projet · Studio Exemple · 2022–2026\n• Coordination d’une équipe de six personnes.\n• Lancement de trois services numériques dans les délais.\n\nChargée de projet · Atelier Exemple · 2020–2022\n• Suivi des budgets et de la relation client.',education:'Master en gestion de projet · Université Exemple · 2020',skills:'Gestion de projet · Recherche utilisateur · Accessibilité · Français · Anglais',projects:'Bénévolat : accompagnement d’une association dans sa transition numérique.'}:{name:'Alex Morgan',headline:'Digital Project Manager',email:'alex@example.com',location:'London, UK',summary:'Project manager with five years of experience delivering accessible digital services. Skilled in team coordination and turning research into practical outcomes.',experience:'Project Manager · Example Studio · 2022–2026\n• Coordinated a team of six across three product launches.\n• Delivered projects on schedule with clear stakeholder reporting.\n\nProject Coordinator · Example Workshop · 2020–2022\n• Managed budgets, schedules and client communication.',education:'MSc Project Management · Example University · 2020',skills:'Project management · User research · Accessibility · English · French',projects:'Volunteer: helped a local nonprofit improve its digital services.'};for(const [id] of resumeFields)$('cv-'+id).value=value[id]||'';render();message('');};
 $('cv-json').onclick=()=>download(new Blob([JSON.stringify({format:'quicktiny-cv',version:1,data:data()},null,2)+'\n'],{type:'application/json'}),'resume.json');$('cv-txt').onclick=()=>download(new Blob([resumeText(data())],{type:'text/plain;charset=utf-8'}),'resume.txt');
 $('cv-import').onchange=async()=>{try{const file=$('cv-import').files[0];if(!file)return;if(file.size>1000000)throw Error('This is not a valid QuickTiny resume JSON file.');const value=validateResume(JSON.parse(await file.text()));for(const [id] of resumeFields)$('cv-'+id).value=value[id];$('cv-accent').value=value.accent;render();message('Resume imported.');}catch(e){message('This is not a valid QuickTiny resume JSON file.',true);}finally{$('cv-import').value='';}};
 $('cv-print').onclick=()=>{const popup=window.open('','_blank');if(!popup){message('Allow pop-ups to open the print view, then try again.',true);return;}const language=document.documentElement.lang==='fr'?'fr':'en';popup.document.open();popup.document.write(`<!doctype html><html lang="${language}"><head><meta charset="utf-8"><title>${escape(data().name||'Resume')}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{margin:0;background:#fff}article{padding:0!important;max-width:none!important}h2{break-after:avoid}p{orphans:3;widows:3}@media print{a{color:inherit;text-decoration:none}}</style></head><body>${resumeHTML(data(),{language,print:true})}</body></html>`);popup.document.close();popup.focus();try{popup.print();}catch{}message('Use Print / Save as PDF and select Save as PDF in the print dialog.');};
 render();
};
